from pathlib import Path
p=Path('acw/inspection.py');s=p.read_text(encoding='utf-8');s=s.replace("return git_read(repo,'diff','--no-ext-diff','--no-textconv','--no-color','HEAD','--')", "from .security import is_secret_path, safe_file\n    listing=git_read(repo,'diff','--name-only','-z','HEAD','--')\n    if listing['exit_code']: return listing\n    allowed=[]\n    for name in listing['stdout'].split('\\0'):\n        if not name or is_secret_path(name): continue\n        try: safe_file(Path(repo)/name,[repo],must_exist=False)\n        except (ValueError,PermissionError): continue\n        allowed.append(name)\n    if not allowed: return {'command':'git diff (credential paths excluded)','cwd':str(repo),'stdout':'','stderr':'','exit_code':0}\n    result=git_read(repo,'diff','--no-ext-diff','--no-textconv','--no-color','HEAD','--',*allowed)\n    result['excluded_secret_paths']=True\n    return result")
p.write_text(s,encoding='utf-8')
